public class O1 {
    static StringBuilder log = new StringBuilder();
    static String make(String tag) { log.append(tag); return tag; }
    public static void main(String[] args) {
        Optional<String> o = Optional.of("v");
        o.orElse(make("A"));
        o.orElseGet(() -> make("B"));
        Optional.<String>empty().orElseGet(() -> make("C"));
        System.out.println(log);
    }
}

